<?php require_once __DIR__.'/../includes/requireLogin.php';require_once __DIR__.'/../includes/authorization.php';require_once __DIR__.'/../includes/csrf.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../repositories/userPDO.php';require_once __DIR__.'/../services/authService.php';requireLogin();requireRole('admin');$id=filter_input(INPUT_GET,'user_id',FILTER_VALIDATE_INT);$p=openDatabase();$u=$id?findUserById($p,$id):false;if(!$u){http_response_code(404);exit('Account not found');}$roles=loadRoles($p,$id);[$canDelete,$deleteReason]=deleteAllowed($p,$id);require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/nav.php';?><main class="container py-4"><h1>Manage account</h1><dl class="row col-md-7"><dt class="col-sm-3">Name</dt><dd class="col-sm-9"><?=htmlspecialchars($u['full_name'],ENT_QUOTES,'UTF-8')?></dd><dt class="col-sm-3">Email</dt><dd class="col-sm-9"><?=htmlspecialchars($u['email'],ENT_QUOTES,'UTF-8')?></dd><dt class="col-sm-3">Role</dt><dd class="col-sm-9"><?=htmlspecialchars(implode(', ',$roles),ENT_QUOTES,'UTF-8')?></dd><dt class="col-sm-3">Status</dt><dd class="col-sm-9"><?=$u['active']?'Active':'Inactive'?></dd></dl><div class="row g-4"><section class="col-md-4"><h2 class="h5">Change role</h2><form method="post" action="process-user-admin.php"><input type="hidden" name="action" value="role"><input type="hidden" name="user_id" value="<?=$id?>"><?=csrfField()?><select class="form-select mb-2" name="role"><?php foreach(['student','tutor','admin'] as $r):?><option value="<?=$r?>" <?=in_array($r,$roles,true)?'selected':''?>><?=$r?></option><?php endforeach;?></select><button class="btn btn-primary">Save role</button></form></section><section class="col-md-4"><h2 class="h5">Account status</h2><form method="post" action="process-user-admin.php"><input type="hidden" name="action" value="status"><input type="hidden" name="user_id" value="<?=$id?>"><?=csrfField()?><input type="hidden" name="active" value="<?=$u['active']?'0':'1'?>"><p><?=$u['active']?'Deactivate this account?':'Activate this account?'?></p><button class="btn btn-warning"><?=$u['active']?'Deactivate':'Activate'?></button></form></section><section class="col-md-4"><h2 class="h5">Delete account</h2><?php if($canDelete):?><form method="post" action="process-user-admin.php"><input type="hidden" name="action" value="delete"><input type="hidden" name="user_id" value="<?=$id?>"><?=csrfField()?><p>Deletion is permanent.</p><button class="btn btn-danger">Confirm delete</button></form><?php else:?><p class="text-muted"><?=htmlspecialchars($deleteReason,ENT_QUOTES,'UTF-8')?></p><?php endif;?></section></div><p class="mt-4"><a href="manage-users.php">Return to account list</a></p></main><?php require __DIR__.'/../includes/footer.php';?>
